import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"27、【頤】 震下艮上","description":"周易口訣義 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"周易口訣義 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/koujueyi/029.md","filePath":"classics/koujueyi/029.md"}'),r={name:"classics/koujueyi/029.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><p>彖曰：「頤，貞吉」，養正則吉也。「觀頤」，觀其所養也。「自求口實」，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉！</p><p>象曰：山下有雷，頤。君子以慎言語，節飲食。</p><p>初九，舍爾靈龜，觀我朵頤，兇。</p><p>象曰：「觀我朵頤」，亦不足貴也。</p><p>六二，顛頤，拂經，於丘頤，徵兇。</p><p>象曰：六二「徵兇」，行失類也。</p><p>六三，拂頤，貞兇，十年勿用，無攸利。</p><p>象曰：「十年勿用」，道大悖也。</p><p>六四，顛頤，吉。虎視眈眈，其欲逐逐，無咎。</p><p>象曰：「顛頤」之吉，上施光也。</p><p>六五，拂經，居貞吉，不可涉大川。</p><p>象曰：「居貞」之吉，順以從上也。</p><p>上九，由頤，厲吉，利涉大川。象曰：「由頤厲吉」，大有慶也。</p><p>解讀</p><p>「頤貞吉」者，頤，養也，養正則吉，故曰「頤貞吉」也。「觀頤」者，謂在下之人，觀其君上所養之人，若所養之人賢良，即能助君行化也。「自求口實」者，謂其自養，求其口中之實物，飲食不節，患必生焉，故荀爽雲「飲食失宜，患之所起」是也。象曰「山下有雷，頤」者，艮止於上，雷動於下，猶人口動，咀嚼飲食，皆下動上止，頤之象也。「君子以慎言語，節飲食」者，啟發言語，榮辱之階，不可不慎；飲食過傷，患之所起，不得不節也。</p><p>「初九，舍爾靈龜，觀我朵頤，兇」者，「靈龜」，謂神靈明兆之物，喻己之明德；朵，猶動嚼也，喻貪婪躁求。食祿之人，當養賢之初，不能修德待用，而貪羨它人，躁欲求之，如舍已明德，貪竊躁求，所以「兇」也。</p><p>「六二，顛頤，拂經，於丘頤，徵兇」者，顛，倒也，謂倒下養初也；拂，違也；經猶義也；丘，所履之常。凡頤養之道，只合以下養上，今既倒下養初，即是違於經義所履之常，以此而養，所行必兇，故曰「頤，徵兇」也。</p><p>「六三拂頤，貞兇，十年勿用，無攸利」者，頤養之體，貴於守正，今六三以陰居陽，是納上以謟媚也。既為謟行，違養之道，是正之兇矣。雖復十年，猶未可見用，故無施而利，故曰「無攸利」也。</p><p>「六四，顛頤，吉。虎視耽耽，其欲逐逐，無咎」者，「耽耽」，威肅也；「逐逐」，敦實也；以上養下，所養賢人，故曰「顛頤，吉」也。親德養賢也，不可以慢，必須威而不猛，如虎之視近志遠，雖不怒而有威，又須寡慾少求，情志逐逐。修此二德，是頤養之美，故「無咎」也。</p><p>「六五：拂經，居貞吉。不可涉大川」者，以陰居陽而位不正，是違經義。若居之能守貞正即吉，以不正之身而處尊位，故「不利涉大川」也。</p><p>上九：由頤，厲吉。「利涉大川」者，四陰皆宗歸上，莫不由上九而養之，故曰「由頤」也。為眾陰之主，又非其尊位，不可以慢，故嚴厲乃得吉，故曰「厲吉」。為眾之主，既能嚴正，即物不敢違，故「利涉大川」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
